import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ViewerPanel } from './components/ViewerPanel';
import { projectApi } from './services/api';
import type { Project, ImageMetadata, DSMStatistics, HistoryResponse, TerrainInspection, GCPInput, ProcessSettings, AnalysisRun } from './types';
import './App.css';

type Page='overview'|'project'|'reconstruction'|'calibration'|'validation'|'terrain'|'inspection'|'analysis'|'benchmark'|'history'|'exports'|'settings';
const nav: {id:Page;icon:string;label:string;group:string}[]=[
 {id:'overview',icon:'⌂',label:'Overview',group:'WORKSPACE'}, {id:'project',icon:'▣',label:'Project',group:'WORKSPACE'},
 {id:'reconstruction',icon:'✦',label:'Reconstruction',group:'WORKSPACE'}, {id:'calibration',icon:'⌁',label:'Calibration',group:'WORKSPACE'},
 {id:'validation',icon:'✓',label:'Validation',group:'WORKSPACE'}, {id:'terrain',icon:'◇',label:'3D Terrain',group:'EXPLORE'},
 {id:'inspection',icon:'⌖',label:'Inspection',group:'EXPLORE'}, {id:'analysis',icon:'◌',label:'Error Analysis',group:'ANALYSIS'}, {id:'benchmark',icon:'▥',label:'Model Benchmark',group:'ANALYSIS'},
 {id:'history',icon:'▤',label:'History',group:'ANALYSIS'}, {id:'exports',icon:'⇩',label:'Exports',group:'OUTPUT'}, {id:'settings',icon:'⚙',label:'Settings',group:'SYSTEM'}
];
const fmt=(v:any,d=2)=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(d):'—';
const dt=(s?:string)=>s?new Date(s).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'—';
const stateLabel=(s:string)=>(s||'READY').replace(/_/g,' ');
type ModelStatus={id:string;label:string;available:boolean;status:string;provenance?:any};
function Badge({state}:{state:string}){const cls=state==='FAILED'?'bad':['READY','VALIDATED'].includes(state)?'good':['NEW','UPLOADED'].includes(state)?'neutral':'busy';return <span className={`badge ${cls}`}><i/>{stateLabel(state)}</span>}

export default function App(){
 const [project,setProject]=useState<Project|null>(null),[page,setPage]=useState<Page>('overview');
 const [meta,setMeta]=useState<ImageMetadata|null>(null),[stats,setStats]=useState<DSMStatistics|null>(null),[history,setHistory]=useState<HistoryResponse|null>(null),[inspection,setInspection]=useState<TerrainInspection|null>(null);
 const [notice,setNotice]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState('');
 const [collapsed,setCollapsed]=useState(false),[paletteOpen,setPaletteOpen]=useState(false),[activityOpen,setActivityOpen]=useState(false),[projectMenu,setProjectMenu]=useState(false);
 const [projectName,setProjectName]=useState(''),[projects,setProjects]=useState<Project[]>([]),[projectsOpen,setProjectsOpen]=useState(false),[modelStatus,setModelStatus]=useState<ModelStatus[]>([]);
 const [settings,setSettings]=useState<ProcessSettings>({model_name:'depth-anything-v2-small',inference_resolution:768,tile_size:768,tile_overlap:.25,edge_refinement:true,terrain_smoothing:true});
 const [snapshots,setSnapshots]=useState<any[]>([]);
 const [calFile,setCalFile]=useState<File|null>(null),[fraction,setFraction]=useState(.8),[seed,setSeed]=useState(42),[gcps,setGcps]=useState<GCPInput[]>([{pixel_x:0,pixel_y:0,reference_elevation:0},{pixel_x:0,pixel_y:0,reference_elevation:0},{pixel_x:0,pixel_y:0,reference_elevation:0}]);
 const [refFile,setRefFile]=useState<File|null>(null),[holdout,setHoldout]=useState(true),[refType,setRefType]=useState('DEM');
 const [gridVisible,setGridVisible]=useState(true),[terrainPanel,setTerrainPanel]=useState(true),[confirm,setConfirm]=useState<{kind:'reset'|'delete'|'deleteRun';run?:{type:string;id:string}}|null>(null);
  const poll = useRef<number | null>(null);
  const refreshSeq = useRef(0);

  const loadSnapshots = useCallback(async (id: string) => {
    try {
      setSnapshots(await projectApi.listSnapshots(id));
    } catch {
      setSnapshots([]);
    }
  }, []);

  const loadProjects = useCallback(async () => {
    try {
      setProjects(await projectApi.list());
    } catch {}
  }, []);

  const loadModels = useCallback(async () => {
    try {
      setModelStatus(await projectApi.listModels());
    } catch {
      setModelStatus([]);
    }
  }, []);

  const refresh = useCallback(
    async (id: string) => {
      const seq = ++refreshSeq.current;

      // Clear project-specific state first so stale metadata never remains visible.
      setMeta(null);
      setStats(null);
      setHistory(null);
      setInspection(null);
      setSnapshots([]);

      const p = await projectApi.get(id);

      if (seq !== refreshSeq.current) return;

      setProject(p);

      const [h, m, s] = await Promise.all([
        projectApi.getHistory(id),
        projectApi.getMetadata(id).catch(() => null),
        projectApi.getStatistics(id).catch(() => null),
      ]);

      if (seq !== refreshSeq.current) return;

      setHistory(h);
      setMeta(m);
      setStats(s);

      await loadSnapshots(id);

      if (h.reconstruction_history?.[0]?.settings) {
        setSettings((prev) => ({
          ...prev,
          ...h.reconstruction_history[0].settings,
        }));
      }
    },
    [loadSnapshots]
  );

  useEffect(() => {
    const id = localStorage.getItem('depthwizard.projectId');

    if (id) {
      refresh(id).catch(() =>
        localStorage.removeItem('depthwizard.projectId')
      );
    }

    loadProjects();
    loadModels();
  }, [refresh, loadProjects, loadModels]);

  useEffect(() => {
    return () => {
      if (poll.current) {
        clearInterval(poll.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!notice) return;

    const t = window.setTimeout(() => setNotice(''), 3200);

    return () => window.clearTimeout(t);
  }, [notice]);
 useEffect(()=>()=>{if(poll.current)clearInterval(poll.current)},[]);
 useEffect(()=>{if(!notice)return; const t=window.setTimeout(()=>setNotice(''),3200); return()=>window.clearTimeout(t)},[notice]);
 useEffect(()=>{const key=(e:KeyboardEvent)=>{const k=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&k==='k'){e.preventDefault();setPaletteOpen(v=>!v)}else if((e.ctrlKey||e.metaKey)&&k==='n'){e.preventDefault();newProject()}else if((e.ctrlKey||e.metaKey)&&k==='s'){e.preventDefault();setNotice('Project state is persisted automatically. Snapshot-ready state saved.') }else if(k==='g'&&page==='terrain'){setGridVisible(v=>!v)}else if(k==='i'){setPage('inspection')}else if(k==='escape'){setPaletteOpen(false);setProjectMenu(false);setConfirm(null)}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[page]);
 const run=async(label:string,fn:()=>Promise<any>)=>{setBusy(label);setError('');setNotice('');try{await fn();if(project)await refresh(project.project_id);setNotice(`${label} completed`)}catch(e:any){setError(e?.response?.data?.detail||e?.message||`${label} failed`)}finally{setBusy('')}};
 async function newProject(){setProjectMenu(false);setProjectsOpen(false);const name=window.prompt('New DepthWizard project name','Untitled terrain project');if(!name?.trim())return;setBusy('Project creation');setError('');try{const p=await projectApi.create(name.trim(),'DepthWizard integrated geospatial elevation project');setProject(p);setMeta(null);setStats(null);setHistory({calibration_history:[],validation_history:[],reconstruction_history:[],inspection_history:[]});setSnapshots([]);setInspection(null);localStorage.setItem('depthwizard.projectId',p.project_id);setPage('project');await loadProjects();setNotice('New project created')}catch(e:any){setError(e?.response?.data?.detail||e?.message||'Project creation failed')}finally{setBusy('')}}
 const switchProject=async(id:string)=>{setProjectsOpen(false);setProjectMenu(false);localStorage.setItem('depthwizard.projectId',id);setPage('overview');try{await refresh(id)}catch(e:any){setError(e?.message||'Unable to open project')}};
 const upload=async(file:File)=>{if(!project)return;await run('Upload',async()=>{await projectApi.upload(project.project_id,file);setCalFile(null);setRefFile(null);setPage('reconstruction')})};
 const process=async()=>{if(!project)return;const pid=project.project_id;setBusy('Reconstruction');setError('');setNotice('');try{await projectApi.process(pid,settings);const check=async()=>{try{const p=await projectApi.getStatus(pid);setProject(p);if(['READY','VALIDATED','FAILED'].includes(p.state)||p.job_state==='completed'||p.job_state==='failed'){if(poll.current)clearInterval(poll.current);poll.current=null;await refresh(pid);setBusy('');if(p.state!=='FAILED'&&p.job_state!=='failed'){setPage('terrain');setNotice('Reconstruction complete · 3D Terrain opened automatically')}}}catch(e:any){if(poll.current)clearInterval(poll.current);poll.current=null;setBusy('');setError(e?.message||'Reconstruction status check failed')}};await check();if(!poll.current)poll.current=window.setInterval(check,350)}catch(e:any){setBusy('');setError(e?.response?.data?.detail||e?.message||'Reconstruction failed')}};
 const calibrate=async(method:'dem'|'gcp')=>{if(!project)return;if(method==='dem'&&!calFile){setError('Select a reference DEM GeoTIFF first');return}await run(`${method.toUpperCase()} calibration`,async()=>{if(method==='dem')await projectApi.calibrateDem(project.project_id,calFile!,fraction,seed);else await projectApi.calibrate(project.project_id,'gcp',gcps,fraction,seed);setPage('validation')})};
 const validate=async()=>{if(!project||!refFile){setError('Select a reference raster first');return}await run('Validation',async()=>{await projectApi.validate(project.project_id,refFile,holdout,refType);setPage('terrain')})};
 const reset=async()=>{if(!project)return;await run('Project reset',async()=>{await projectApi.reset(project.project_id);await refresh(project.project_id);setCalFile(null);setRefFile(null);setPage('project')});setConfirm(null)};
 const removeProject=async()=>{if(!project)return;const id=project.project_id;setBusy('Project deletion');setError('');setNotice('');try{await projectApi.remove(id);localStorage.removeItem('depthwizard.projectId');setProject(null);setMeta(null);setStats(null);setHistory(null);setInspection(null);setPage('overview');await loadProjects();setNotice('Project deleted')}catch(e:any){setError(e?.response?.data?.detail||e?.message||'Project deletion failed')}finally{setBusy('');setConfirm(null)}};
 const renameProject=async()=>{if(!project)return;const name=window.prompt('Rename project',project.name);if(!name?.trim()||name.trim()===project.name)return;await run('Project rename',async()=>{await projectApi.rename(project.project_id,name.trim());await loadProjects()})};
 const deleteRun=async()=>{if(!project||!confirm?.run)return;await run('History deletion',async()=>{await projectApi.deleteHistory(project.project_id,confirm.run!.type,confirm.run!.id);});setConfirm(null)};
 const ready=!!project&&['READY','VALIDATED'].includes(project.state); const metric=project?.reconstruction_mode==='metric';
 const recent=useMemo(()=>[...(history?.validation_history||[]).map(x=>({...x,_type:'Validation'})),...(history?.calibration_history||[]).map(x=>({...x,_type:'Calibration'})),...(history?.reconstruction_history||[]).map(x=>({...x,_type:'Reconstruction'}))].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,10),[history]);
 const saveSnapshot=async()=>{if(!project)return;setBusy('Snapshot');try{const name=window.prompt('Snapshot name',`Snapshot ${snapshots.length+1}`)||undefined;await projectApi.createSnapshot(project.project_id,name);await loadSnapshots(project.project_id);setNotice('Snapshot saved');}catch(e:any){setError(e?.response?.data?.detail||e?.message||'Snapshot failed')}finally{setBusy('')}};
 const next=useMemo(()=>{if(!project)return {label:'Create a project',page:'overview' as Page};if(!meta)return {label:'Upload source imagery',page:'project' as Page};if(!history?.reconstruction_history?.length)return {label:'Run reconstruction',page:'reconstruction' as Page};if(!metric)return {label:'Calibrate elevation',page:'calibration' as Page};if(!history?.validation_history?.length)return {label:'Validate against reference',page:'validation' as Page};return {label:'Explore 3D terrain',page:'terrain' as Page}},[project,meta,history,metric]);
 return <div className="app-shell">
  <header className="topbar">
   <div className="brand-lock"><button className="brand-mark" onClick={()=>setCollapsed(v=>!v)} title="Toggle navigation">◇</button><div><b>DepthWizard</b><span>AI elevation intelligence</span></div></div>
   <div className="project-switcher"><button className="project-button" onClick={()=>setProjectMenu(v=>!v)}><span className="eyebrow">PROJECT</span><strong>{project?.name||'No project selected'}</strong><span>⌄</span></button>{projectMenu&&<div className="project-menu"><button onClick={newProject}>＋ New project <kbd>Ctrl N</kbd></button>{project&&<><div className="menu-divider"/><button onClick={renameProject}>Rename current project</button><button onClick={()=>setConfirm({kind:'reset'})}>Reset current project</button><button onClick={()=>setConfirm({kind:'delete'})}>Delete current project</button></>}{projects.length>0&&<><div className="menu-divider"/><div className="menu-caption">RECENT PROJECTS</div>{projects.slice(0,8).map(p=><button key={p.project_id} onClick={()=>switchProject(p.project_id)} className={p.project_id===project?.project_id?'selected':''}><span><b>{p.name}</b><small>{stateLabel(p.state)} · {dt(p.updated_at)}</small></span><Badge state={p.state}/></button>)}</>}</div>}</div>
   <div className="top-actions"><button className="search-button" onClick={()=>setPaletteOpen(true)}>⌕ <span>Search</span><kbd>Ctrl K</kbd></button><button className="top-icon" onClick={saveSnapshot} title="Save snapshot">⌘</button><button className="top-icon" onClick={()=>setActivityOpen(v=>!v)} title="Activity">◔</button><Badge state={project?.state||'NEW'}/><button className="top-icon" title="Help">?</button><button className="top-icon" onClick={()=>setPage('settings')} title="Settings">⚙</button></div>
  </header>
  {activityOpen&&<Activity history={history} close={()=>setActivityOpen(false)}/>} {paletteOpen&&<Palette project={project} close={()=>setPaletteOpen(false)} setPage={setPage} />}
  <div className={`app-body ${page==='terrain'?'terrain-layout':'standard-layout'}`}>
   <aside className={`sidebar ${collapsed?'collapsed':''}`}><div className="side-toggle"><button onClick={()=>setCollapsed(v=>!v)}>{collapsed?'→':'←'}</button></div>{['WORKSPACE','EXPLORE','ANALYSIS','OUTPUT','SYSTEM'].map(group=><div className="nav-group" key={group}><div className="nav-caption">{group}</div>{nav.filter(x=>x.group===group).map(n=><button key={n.id} className={`nav-link ${page===n.id?'active':''}`} onClick={()=>setPage(n.id)} title={collapsed?n.label:undefined}><span>{n.icon}</span><em>{n.label}</em></button>)}</div>)}<div className="side-footer"><span className="engine-live"/>LOCAL ENGINE<small>Standalone · private</small></div></aside>
   <main className={`main-area ${page==='terrain'?'terrain-main':''}`}>{error&&<div className="toast error">⚠ <span>{error}</span><button onClick={()=>setError('')}>×</button></div>}{notice&&<div className="toast success">✓ <span>{notice}</span><button onClick={()=>setNotice('')}>×</button></div>}{busy==='Reconstruction'&&project&&<div className="global-processing"><Progress project={project}/></div>}
    {!project ? <Welcome projectName={projectName} setProjectName={setProjectName} create={async()=>{if(!projectName.trim())return;await run('Project creation',async()=>{const p=await projectApi.create(projectName.trim(),'DepthWizard integrated geospatial elevation project');setProject(p);localStorage.setItem('depthwizard.projectId',p.project_id);setProjectName('');setPage('project');await loadProjects()})}} onNew={newProject}/>:<>
     <Workflow project={project} meta={meta} history={history} page={page} setPage={setPage}/>
     {page==='overview'&&<Overview project={project} meta={meta} stats={stats} history={history} next={next} setPage={setPage}/>} 
     {page==='project'&&<ProjectPage project={project} meta={meta} history={history} upload={upload} busy={!!busy} setPage={setPage}/>} 
     {page==='reconstruction'&&<Reconstruction settings={settings} setSettings={setSettings} run={process} busy={busy==='Reconstruction'} project={project} history={history} setPage={setPage} modelStatus={modelStatus}/>} 
     {page==='calibration'&&<Calibration project={project} meta={meta} metric={metric} file={calFile} setFile={setCalFile} fraction={fraction} setFraction={setFraction} seed={seed} setSeed={setSeed} gcps={gcps} setGcps={setGcps} calibrate={calibrate} busy={busy} history={history}/>} 
     {page==='validation'&&<Validation history={history} file={refFile} setFile={setRefFile} holdout={holdout} setHoldout={setHoldout} refType={refType} setRefType={setRefType} validate={validate} busy={busy} project={project}/>} 
     {page==='terrain'&&<div className="terrain-page"><ViewerPanel project={project} onInspection={setInspection} inspection={inspection} history={history} meta={meta} stats={stats} gridVisible={gridVisible} setGridVisible={setGridVisible} panelOpen={terrainPanel} setPanelOpen={setTerrainPanel}/></div>}
     {page==='inspection'&&<Inspection inspection={inspection} history={history} setPage={setPage}/>} 
     {page==='analysis'&&<Analysis project={project} history={history}/>}
     {page==='benchmark'&&<Benchmark history={history} setPage={setPage}/>} 
     {page==='history'&&<HistoryPage history={history} recent={recent} snapshots={snapshots} requestDelete={(type,id)=>setConfirm({kind:'deleteRun',run:{type,id}})}/>} 
     {page==='exports'&&<Exports project={project} ready={ready}/>} 
     {page==='settings'&&<SettingsPage settings={settings} setSettings={setSettings} modelStatus={modelStatus}/>} 
    </>}
   </main>
  </div>
  {project&&page!=='terrain'&&<div className="quickbar"><span>{next.label}</span><button onClick={()=>setPage(next.page)}>Next step →</button><button onClick={()=>setConfirm({kind:'reset'})} className="ghost-danger">Reset</button></div>}
  {confirm&&<ConfirmModal confirm={confirm} close={()=>setConfirm(null)} onConfirm={confirm.kind==='reset'?reset:confirm.kind==='delete'?removeProject:deleteRun}/>} 
 </div>
}

function Welcome({projectName,setProjectName,create,onNew}:{projectName:string;setProjectName:(v:string)=>void;create:()=>void;onNew:()=>void}){return <div className="welcome"><div className="welcome-mark">◇</div><div className="eyebrow">SINGLE-VIEW TERRAIN INTELLIGENCE</div><h1>RGB → Elevation → 3D Terrain</h1><p>Build a reproducible elevation surface from a single image, calibrate it against geospatial references, validate accuracy, and explore the result interactively.</p><div className="create-row"><input value={projectName} onChange={e=>setProjectName(e.target.value)} placeholder="Project name" onKeyDown={e=>e.key==='Enter'&&create()}/><button className="btn primary" onClick={create}>Create project →</button></div><button className="link-button" onClick={onNew}>＋ Start a new project</button><div className="capability-grid"><Capability n="01" t="Reconstruct" s="Depth Anything V2 · tiled inference"/><Capability n="02" t="Calibrate" s="DEM or GCP metric elevation"/><Capability n="03" t="Validate" s="Holdout RMSE · MAE · R² · P95"/><Capability n="04" t="Explore" s="3D flythrough · inspection · export"/></div></div>}
function Capability({n,t,s}:{n:string;t:string;s:string}){return <div><span>{n}</span><b>{t}</b><small>{s}</small></div>}
function Workflow({project,meta,history,page,setPage}:{project:Project;meta:ImageMetadata|null;history:HistoryResponse|null;page:Page;setPage:(p:Page)=>void}){const steps:[string,Page,boolean][]=[['Prepare','project',!!meta],['Reconstruct','reconstruction',!!history?.reconstruction_history?.length],['Calibrate','calibration',project.reconstruction_mode==='metric'],['Validate','validation',!!history?.validation_history?.length],['Explore','terrain',page==='terrain'],['Inspect','inspection',(history?.inspection_history?.length||0)>0],['Export','exports',false]];return <div className="workflow"><div className="workflow-line"/>{steps.map(([label,p,done],i)=><button key={label} className={`workflow-step ${done?'done':''} ${page===p?'current':''}`} onClick={()=>setPage(p)}><span>{done?'✓':String(i+1).padStart(2,'0')}</span><b>{label}</b></button>)}</div>}

function Overview({project,meta,stats,history,next,setPage}:{project:Project;meta:ImageMetadata|null;stats:DSMStatistics|null;history:HistoryResponse|null;next:{label:string;page:Page};setPage:(p:Page)=>void}){const v=history?.validation_history?.[0];return <div className="page"><PageHead kicker="PROJECT COMMAND CENTER" title={project.name} sub="One project state drives imagery, reconstruction, calibration, validation, terrain and history." actions={<><button className="btn" onClick={()=>setPage('project')}>Project</button><button className="btn primary" onClick={()=>setPage(next.page)}>{next.label} →</button></>}/><div className="hero-status"><div><span className="eyebrow">PROJECT STATUS</span><h2><Badge state={project.state}/></h2><p>{project.message||'Ready for the next workflow step.'}</p></div><div className="hero-next"><span>NEXT RECOMMENDED ACTION</span><b>{next.label}</b><button onClick={()=>setPage(next.page)}>Open workspace →</button></div></div><div className="metric-grid"><Metric label="RMSE" value={v?`${fmt(v.rmse)} m`:'—'} note="Latest validation"/><Metric label="MAE" value={v?`${fmt(v.mae)} m`:'—'}/><Metric label="R²" value={v?fmt(v.r2,3):'—'}/><Metric label="Valid coverage" value={stats?`${fmt(stats.valid_pixel_percentage,1)}%`:'—'}/></div><div className="dashboard-grid"><section className="card"><CardTitle title="Input intelligence" meta={meta?'Current project':'Awaiting imagery'}/><DataRows rows={[["Source",meta?.filename],["Raster",meta?`${meta.width} × ${meta.height}`:undefined],["Bands",meta?.band_count||meta?.channels],["CRS",meta?.crs||'Not georeferenced'],["Resolution",meta?.resolution?`${fmt(meta.resolution[0],3)} × ${fmt(meta.resolution[1],3)}`:undefined]]}/></section><section className="card"><CardTitle title="Surface summary" meta={stats?.is_metric?'Metric':'Relative'}/><DataRows rows={[["Minimum",stats?`${fmt(stats.min_elevation)} ${stats.unit}`:undefined],["Maximum",stats?`${fmt(stats.max_elevation)} ${stats.unit}`:undefined],["Mean",stats?`${fmt(stats.mean_elevation)} ${stats.unit}`:undefined],["Range",stats?`${fmt(stats.elevation_range)} ${stats.unit}`:undefined],["Mean slope",stats?.slope_mean!==undefined?`${fmt(stats.slope_mean)}°`:undefined]]}/></section><section className="card span-2"><CardTitle title="Workflow health"/><HealthRow label="Source imagery" ok={!!meta} text={meta?'Loaded and metadata refreshed':'Upload JPG, PNG or GeoTIFF'}/><HealthRow label="Reconstruction" ok={!!history?.reconstruction_history?.length} text={history?.reconstruction_history?.length?`${history.reconstruction_history.length} run(s) preserved`:'Not run'}/><HealthRow label="Calibration" ok={project.reconstruction_mode==='metric'} text={project.reconstruction_mode==='metric'?'Metric elevation active':'Relative surface'}/><HealthRow label="Validation" ok={!!v} text={v?`${fmt(v.rmse)} m RMSE · ${fmt(v.valid_pixel_percentage,1)}% coverage`:'Not run'}/></section></div></div>}
function ProjectPage({project,meta,history,upload,busy,setPage}:any){const ref=useRef<HTMLInputElement>(null);return <div className="page"><PageHead kicker="PROJECT" title="Project & imagery" sub="The project workspace is the entry point for the entire pipeline." actions={<button className="btn primary" onClick={()=>setPage('reconstruction')} disabled={!meta}>Continue to reconstruction →</button>}/><div className="project-overview-strip"><div><span>STATUS</span><b><Badge state={project.state}/></b></div><div><span>MODE</span><b>{project.reconstruction_mode==='metric'?'Metric DSM':'Relative DSM'}</b></div><div><span>RUNS</span><b>{history?.reconstruction_history?.length||0}</b></div><div><span>UPDATED</span><b>{dt(project.updated_at)}</b></div></div><div className="dashboard-grid"><section className="card upload-card"><CardTitle title="Source imagery" meta={meta?'Current source':'Required'}/><div className="dropzone" onClick={()=>ref.current?.click()}><div className="drop-icon">↑</div><b>{meta?'Replace source imagery':'Choose source imagery'}</b><small>JPG · PNG · GeoTIFF · up to 500 MB</small><input ref={ref} hidden type="file" accept=".jpg,.jpeg,.png,.tif,.tiff" onChange={e=>{const f=e.target.files?.[0];if(f)upload(f);e.currentTarget.value=''}}/></div></section><section className="card"><CardTitle title="Spatial metadata" meta={meta?'LIVE · CURRENT PROJECT':'Awaiting upload'}/>{meta?<DataRows rows={[["Filename",meta.filename],["Raster size",`${meta.width} × ${meta.height}`],["Bands",meta.band_count||meta.channels],["CRS",meta.crs||'None'],["GSD",meta.resolution?`${fmt(meta.resolution[0],3)} × ${fmt(meta.resolution[1],3)}`:'—'],["NoData",meta.nodata??'—']]}/>:<EmptyHint text="Metadata is cleared when the project changes. Upload imagery to populate this panel." action="Upload imagery"/>}</section><section className="card span-2"><CardTitle title="Pipeline control" meta="Connected workflow"/><div className="pipeline-cards"><PipelineCard n="01" title="Reconstruction" text={history?.reconstruction_history?.length?`${history.reconstruction_history.length} preserved run(s)`:'Generate relative depth and terrain'} done={!!history?.reconstruction_history?.length} onClick={()=>setPage('reconstruction')}/><PipelineCard n="02" title="Calibration" text={project.reconstruction_mode==='metric'?'Metric elevation active':'DEM or GCP calibration'} done={project.reconstruction_mode==='metric'} onClick={()=>setPage('calibration')}/><PipelineCard n="03" title="Validation" text={history?.validation_history?.length?`${fmt(history.validation_history[0].rmse)} m RMSE`:'Independent reference validation'} done={!!history?.validation_history?.length} onClick={()=>setPage('validation')}/><PipelineCard n="04" title="3D Terrain" text={history?.reconstruction_history?.length?'Interactive flythrough ready':'Available after reconstruction'} done={!!history?.reconstruction_history?.length} onClick={()=>setPage('terrain')}/></div></section></div><div className="callout"><b>Spatial integrity</b><span>Current-project metadata is fetched after every project switch/upload; stale CRS, dimensions and pixel size are never intentionally retained.</span></div></div>}
function PipelineCard({n,title,text,done,onClick}:{n:string;title:string;text:string;done:boolean;onClick:()=>void}){return <button className="pipeline-card" onClick={onClick}><span>{done?'✓':n}</span><div><b>{title}</b><small>{text}</small></div><strong>→</strong></button>}
function Reconstruction({settings,setSettings,run,busy,project,history,setPage,modelStatus}:any){const set=(k:string,v:any)=>setSettings((s:ProcessSettings)=>({...s,[k]:v})); const aerial=modelStatus?.find((m:ModelStatus)=>m.id==='aerial-depth');return <div className="page"><PageHead kicker="AI ENGINE" title="Reconstruction" sub="Configure a reproducible monocular depth pipeline. New reconstruction runs invalidate current calibration/validation while preserving their history." actions={<button className="btn primary" disabled={!['UPLOADED','READY','VALIDATED'].includes(project.state)||busy} onClick={run}>{busy?'Processing…':'Run reconstruction →'}</button>}/><div className="two-col wide"><section className="card"><CardTitle title="Depth engine" meta="Recorded per run"/><div className="form-grid"><Field label="Model"><select value={settings.model_name} onChange={e=>set('model_name',e.target.value)}><option value="depth-anything-v2-small">Depth Anything V2 · Small</option><option value="depth-anything-v2-base">Depth Anything V2 · Base</option><option value="depth-anything-v2-large">Depth Anything V2 · Large</option><option value="aerial-depth" disabled={!aerial?.available}>Aerial-Depth · {aerial?.available?"trained":"not trained"}</option></select></Field><Field label="Inference resolution"><select value={settings.inference_resolution} onChange={e=>set('inference_resolution',+e.target.value)}><option value="518">518 px</option><option value="768">768 px</option><option value="1024">1024 px</option></select></Field><Field label="Tile size"><input type="number" min={256} max={2048} value={settings.tile_size} onChange={e=>set('tile_size',+e.target.value)}/></Field><Field label="Tile overlap"><input type="number" min={0} max={.5} step={.05} value={settings.tile_overlap} onChange={e=>set('tile_overlap',+e.target.value)}/></Field></div><div className="toggle-list"><Toggle label="Edge refinement" value={settings.edge_refinement} onChange={v=>set('edge_refinement',v)}/><Toggle label="Terrain smoothing" value={settings.terrain_smoothing} onChange={v=>set('terrain_smoothing',v)}/></div><div className="engine-note"><b>Accuracy policy</b><span>Native raster grid is preserved; tiled inference uses overlap blending; every setting is attached to the reconstruction history. Larger resolution/models are not assumed to improve RMSE until measured.</span></div><div className={`engine-note ${aerial?.available?'':'warning'}`}><b>Aerial-Depth</b><span>{aerial?.available?'Verified local checkpoint available; provenance and held-out metrics are recorded with deployment.':'Not trained / not benchmarked. Complete the bundled aerial training protocol before enabling production use.'}</span></div></section><section className="card"><CardTitle title="Pipeline" meta="01 → 04"/><div className="pipeline"><Step n="01" t="Read imagery" s="GSD · CRS · NoData" state={project.progress>=.18?'done':project.progress>0?'active':''}/><Step n="02" t="Infer depth" s="Overlapping tiles · live" state={project.progress>=.50?'done':project.progress>=.18?'active':''}/><Step n="03" t="Refine surface" s="Optional edge + terrain processing" state={project.progress>=.70?'done':project.progress>=.50?'active':''}/><Step n="04" t="Generate DSM" s="Raster · slope · mesh" state={project.progress>=1?'done':project.progress>=.70?'active':''}/></div><div className="run-summary"><span>Previous reconstructions</span><b>{history?.reconstruction_history?.length||0}</b><button onClick={()=>setPage('history')}>View history →</button></div></section></div></div>}
function Calibration({project,meta,file,setFile,fraction,setFraction,seed,setSeed,gcps,setGcps,calibrate,busy,history}:any){const ref=useRef<HTMLInputElement>(null);const update=(i:number,k:keyof GCPInput,v:number)=>setGcps((g:GCPInput[])=>g.map((x,j)=>j===i?{...x,[k]:v}:x));return <div className="page"><PageHead kicker="CALIBRATION" title="Metric elevation" sub="Convert scale-ambiguous relative height into real-world elevation using a reference DEM or known GCPs."/><div className="callout info"><b>Current state</b><span>{project.reconstruction_mode==='metric'?`Metric DSM active · current calibration ${project.calibration_type.toUpperCase()}`:'Relative DSM. Calibration is required before metric validation.'}</span></div><div className="two-col wide"><section className="card"><CardTitle title="DEM calibration" meta={meta?.is_georeferenced?'GeoTIFF ready':'Requires georeferenced source'}/><div className="dropzone compact" onClick={()=>ref.current?.click()}><div className="drop-icon">⇩</div><b>{file?.name||'Select reference DEM'}</b><small>Aligned to the source grid before fitting scale + offset</small><input ref={ref} hidden type="file" accept=".tif,.tiff" onChange={e=>setFile(e.target.files?.[0]||null)}/></div><div className="form-grid"><Field label="Calibration fraction"><input type="number" min={.1} max={.95} step={.05} value={fraction} onChange={e=>setFraction(+e.target.value)}/></Field><Field label="Random seed"><input type="number" value={seed} onChange={e=>setSeed(+e.target.value)}/></Field></div><button className="btn primary full" disabled={!file||busy||!meta?.is_georeferenced} onClick={()=>calibrate('dem')}>{busy==='DEM calibration'?'Calibrating…':'Run DEM calibration →'}</button><small className="helper">Default 80/20 split. The calibration mask is retained so holdout validation can exclude calibration pixels.</small></section><section className="card"><CardTitle title="GCP calibration" meta="3+ points"/><p className="muted">Use known elevations when a reference DEM is unavailable. GCP calibration is retained separately and should be validated with independent reference data.</p>{gcps.map((g:GCPInput,i:number)=><div className="gcp-row" key={i}><span>P{i+1}</span><input type="number" placeholder="Pixel X" value={g.pixel_x} onChange={e=>update(i,'pixel_x',+e.target.value)}/><input type="number" placeholder="Pixel Y" value={g.pixel_y} onChange={e=>update(i,'pixel_y',+e.target.value)}/><input type="number" placeholder="Elevation m" value={g.reference_elevation} onChange={e=>update(i,'reference_elevation',+e.target.value)}/></div>)}<button className="btn full" disabled={busy||!project} onClick={()=>calibrate('gcp')}>{busy==='GCP calibration'?'Calibrating…':'Run GCP calibration'}</button></section></div><HistoryStrip title="Calibration history" count={history?.calibration_history?.length||0}/></div>}
function Validation({history,file,setFile,holdout,setHoldout,refType,setRefType,validate,busy,project}:any){const ref=useRef<HTMLInputElement>(null);const current=history?.validation_history?.[0];return <div className="page"><PageHead kicker="VALIDATION" title="Independent accuracy" sub="Evaluate the metric surface against a reference while keeping calibration pixels out of the headline holdout result." actions={<button className="btn primary" disabled={!file||busy||!project||project.reconstruction_mode!=='metric'} onClick={validate}>{busy==='Validation'?'Validating…':'Run validation →'}</button>}/><div className="callout warning"><b>Evaluation integrity</b><span>{holdout?'Independent holdout excludes pixels used for the latest DEM calibration when a saved calibration mask exists.':'Full-reference mode is diagnostic only and should not be presented as an independent benchmark.'}</span></div><div className="two-col wide"><section className="card"><CardTitle title="Reference surface" meta="Spatially aligned"/><div className="dropzone compact" onClick={()=>ref.current?.click()}><div className="drop-icon">⇩</div><b>{file?.name||'Select reference raster'}</b><small>GeoTIFF with CRS or identical raster dimensions</small><input ref={ref} hidden type="file" accept=".tif,.tiff" onChange={e=>setFile(e.target.files?.[0]||null)}/></div><div className="form-grid"><Field label="Reference type"><select value={refType} onChange={e=>setRefType(e.target.value)}><option>DEM</option><option>DSM</option><option>LiDAR-derived</option></select></Field><Field label="Evaluation split"><Toggle label={holdout?'Independent holdout':'Diagnostic full reference'} value={holdout} onChange={setHoldout}/></Field></div></section><section className="card"><CardTitle title="Latest result" meta={current?dt(current.created_at):'Pending'}/>{current?<div className="metric-grid compact"><Metric label="RMSE" value={`${fmt(current.rmse)} m`}/><Metric label="MAE" value={`${fmt(current.mae)} m`}/><Metric label="R²" value={fmt(current.r2,3)}/><Metric label="P95" value={`${fmt(current.p95_abs_error)} m`}/></div>:<EmptyHint text="Run validation after metric calibration." action="Awaiting reference"/>}</section></div><section className="card"><CardTitle title="Validation checklist"/><div className="check-grid"><Check ok={!!file} text="Reference selected"/><Check ok={project.reconstruction_mode==='metric'} text="Metric DSM available"/><Check ok={holdout} text="Holdout integrity enabled"/><Check ok={!!history?.calibration_history?.length||project.calibration_type==='gcp'} text="Calibration provenance recorded"/></div></section></div>}
function Inspection({inspection,history,setPage}:any){return <div className="page"><PageHead kicker="INSPECTION" title="Saved point observations" sub="Select a point in 3D Terrain or review previously saved observations." actions={<button className="btn primary" onClick={()=>setPage('terrain')}>Open 3D Terrain →</button>}/><div className="metric-grid"> <Metric label="Selected elevation" value={inspection?`${fmt(inspection.elevation)} ${inspection.unit||'m'}`:'—'}/><Metric label="Slope" value={inspection?`${fmt(inspection.slope)}°`:'—'}/><Metric label="Pixel" value={inspection?`${inspection.pixel_x}, ${inspection.pixel_y}`:'—'}/><Metric label="Saved points" value={String(history?.inspection_history?.length||0)}/></div><div className="two-col"><section className="card"><CardTitle title="Current point"/>{inspection?<DataRows rows={[["Elevation",`${fmt(inspection.elevation)} ${inspection.unit||'m'}`],["Relative height",inspection.relative_height!==undefined?fmt(inspection.relative_height):'—'],["Slope",`${fmt(inspection.slope)}°`],["Pixel",`${inspection.pixel_x}, ${inspection.pixel_y}`],["World X",fmt(inspection.x,3)],["World Y",fmt(inspection.y,3)]]}/>:<EmptyHint text="Click the terrain surface to inspect elevation." action="Open terrain" onClick={()=>setPage('terrain')}/>}</section><section className="card"><CardTitle title="Recent points" meta="Persistent"/><HistoryTable rows={(history?.inspection_history||[]).map((x:any,i:number)=>({id:`P${i+1}`,date:x.created_at,value:`${fmt(x.elevation)} ${x.unit||'m'}`,sub:`pixel ${x.pixel_x}, ${x.pixel_y}`}))}/></section></div></div>}
function Analysis({project,history}:any){const v=history?.validation_history?.[0];return <div className="page"><PageHead kicker="ERROR ANALYSIS" title="Validation diagnostics" sub="Understand spatial error, evaluation coverage and scientific limitations."/><div className="metric-grid"><Metric label="RMSE" value={v?`${fmt(v.rmse)} m`:'—'}/><Metric label="MAE" value={v?`${fmt(v.mae)} m`:'—'}/><Metric label="Bias" value={v?`${fmt(v.bias)} m`:'—'}/><Metric label="P95" value={v?`${fmt(v.p95_abs_error)} m`:'—'}/></div><section className="card"><CardTitle title="Error map" meta={v?'Latest validation':'Awaiting validation'}/>{v?<div className="large-error"><img src={projectApi.getErrorMapUrl(project.project_id)} alt="Validation error map"/><div className="legend"><span>Negative</span><i/><span>Positive</span></div></div>:<EmptyHint text="Run an independent validation first." action="Awaiting validation"/>}</section><section className="card"><CardTitle title="Scientific interpretation"/><div className="insight-grid"><Insight title="Calibration leakage" text={v?.split?.use_holdout?'Holdout evaluation is active for this run.':'Use independent holdout or GCP + separate reference data for headline claims.'}/><Insight title="Surface semantics" text="DEM references are generally bare-earth. Vegetation and buildings in RGB may legitimately differ from a bare-earth surface."/><Insight title="Model domain" text="Depth Anything V2 is a general monocular model. Aerial-domain fine-tuning is exposed as an explicit experimental engine."/><Insight title="Coverage" text={v?`${fmt(v.valid_pixel_percentage,1)}% of the aligned reference/prediction grid contributed to the reported metrics.`:'Coverage will be reported after validation.'}/></div></section></div>}
function Benchmark({history,setPage}:{history:HistoryResponse|null;setPage:(p:Page)=>void}){const rows=(history?.reconstruction_history||[]).slice(0,8);return <div className="page"><PageHead kicker="MODEL BENCHMARK" title="Measured reconstruction experiments" sub="Compare only completed runs recorded by the backend. No performance values are fabricated or inferred." actions={<button className="btn primary" onClick={()=>setPage('reconstruction')}>Run another experiment →</button>}/><section className="card"><CardTitle title="Experiment matrix" meta={`${rows.length} recorded run(s)`}/>{rows.length?<div className="benchmark-table"><div className="benchmark-head"><span>Run</span><span>Model</span><span>Resolution</span><span>Overlap</span><span>Time</span></div>{rows.map((r:any)=><div className="benchmark-row" key={r.run_id}><b>{r.run_id}</b><span>{r.model||'—'}</span><span>{r.settings?.inference_resolution||'—'} px</span><span>{r.settings?.tile_overlap!==undefined?`${(r.settings.tile_overlap*100).toFixed(0)}%`:'—'}</span><span>{r.processing_seconds!==undefined?`${fmt(r.processing_seconds,1)} s`:'—'}</span></div>)}</div>:<EmptyHint text="No reconstruction experiments have been recorded yet. Run Small, Base or Large with measured settings, then compare them here." action="Configure reconstruction" onClick={()=>setPage('reconstruction')}/>}</section><div className="callout warning"><b>Scientific rule</b><span>Model size, resolution and smoothing are experiment variables. DepthWizard does not claim that a larger model is more accurate until an independent validation run demonstrates it.</span></div></div>}
function HistoryPage({history,recent,snapshots,requestDelete}:{history:HistoryResponse|null;recent:any[];snapshots:any[];requestDelete:(type:string,id:string)=>void}){return <div className="page"><PageHead kicker="ANALYSIS HISTORY" title="Every run, preserved" sub="New experiments never overwrite prior calibration, validation or reconstruction records."/><div className="history-banner"><div><b>{(history?.calibration_history?.length||0)+(history?.validation_history?.length||0)+(history?.reconstruction_history?.length||0)}</b><span>analysis runs</span></div><div><b>{history?.inspection_history?.length||0}</b><span>inspection points</span></div><div><b>{history?.current_calibration_id||'—'}</b><span>current calibration</span></div><div><b>{history?.current_validation_id||'—'}</b><span>current validation</span></div></div><section className="card"><CardTitle title="Timeline" meta="Backend source of truth"/><HistoryTimeline rows={recent}/></section><CompareRuns history={history}/><div className="two-col"><HistoryRunTable title="Reconstruction runs" rows={(history?.reconstruction_history||[]).map((x:any)=>({id:x.run_id,date:x.created_at,value:x.model||'—',sub:x.settings?`${x.settings.inference_resolution||'—'}px · ${(x.settings.tile_overlap??0)*100}% overlap`:''}))} onDelete={requestDelete} type="reconstruction"/><HistoryRunTable title="Calibration runs" rows={(history?.calibration_history||[]).map((x:any)=>({id:x.run_id,date:x.created_at,value:x.rmse!==undefined?`${fmt(x.rmse)} m RMSE`:x.method||'—',sub:x.method||'—'}))} onDelete={requestDelete} type="calibration"/></div><section className="card snapshot-card"><CardTitle title="Saved snapshots" meta="Project state checkpoints"/>{snapshots.length?<div className="snapshot-list">{snapshots.slice(0,12).map((x:any)=><div key={x.snapshot_id}><span><b>{x.name}</b><small>{x.snapshot_id} · {dt(x.created_at)}</small></span><strong>State checkpoint</strong></div>)}</div>:<div className="muted">No snapshots saved yet. Use the top-bar snapshot button to create one.</div>}</section><HistoryRunTable title="Validation runs" rows={(history?.validation_history||[]).map((x:any)=>({id:x.run_id,date:x.created_at,value:x.rmse!==undefined?`${fmt(x.rmse)} m RMSE`:x.method||'—',sub:x.split?.reference_type||'reference'}))} onDelete={requestDelete} type="validation"/></div>}
function CompareRuns({history}:{history:any}){const rows=[...(history?.validation_history||[])].slice(0,4);return <section className="card compare-card"><CardTitle title="Compare validation runs" meta="Latest → oldest"/>{rows.length?<div className="compare-table"><div className="compare-head"><span>Metric</span>{rows.map((r:any)=><b key={r.run_id}>{r.run_id}</b>)}</div>{[['RMSE','rmse','m'],['MAE','mae','m'],['R²','r2',''],['Pearson','pearson_correlation',''],['P95','p95_abs_error','m']].map(([label,key,unit])=><div className="compare-row" key={String(key)}><span>{label}</span>{rows.map((r:any)=><b key={r.run_id}>{fmt(r[key])}{unit?' '+unit:''}</b>)}</div>)}</div>:<EmptyHint text="Run at least one validation to compare experiments." action="Awaiting runs"/>}</section>}
function HistoryRunTable({title,rows,onDelete,type}:{title:string;rows:any[];onDelete:(type:string,id:string)=>void;type:string}){return <section className="card history-run-card"><CardTitle title={title} meta="Persistent"/><div className="history-table">{rows.length?rows.slice(0,20).map(x=><div key={x.id} className="history-table-row"><span><b>{x.id}</b><small>{dt(x.date)}</small></span><strong>{x.value}</strong><small>{x.sub}</small><button className="row-delete" title="Delete history record" onClick={()=>onDelete(type,x.id)}>⋮</button></div>):<div className="muted">No saved runs yet.</div>}</div></section>}
function Activity({history,close}:{history:any;close:()=>void}){const rows=[...(history?.validation_history||[]).map((x:any)=>({...x,t:'Validation'})),...(history?.calibration_history||[]).map((x:any)=>({...x,t:'Calibration'})),...(history?.reconstruction_history||[]).map((x:any)=>({...x,t:'Reconstruction'}))].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,6);return <div className="activity-pop"><div className="pop-head"><b>ACTIVITY</b><button onClick={close}>×</button></div>{rows.length?rows.map((x:any)=><div key={`${x.t}-${x.run_id}`} className="activity-row"><span>✓</span><p><strong>{x.t}</strong><small>{dt(x.created_at)} · {x.rmse!==undefined?`${fmt(x.rmse)} m RMSE`:'Completed'}</small></p></div>):<small className="muted">No activity yet.</small>}</div>}
function Palette({setPage,close,project}:{setPage:(p:Page)=>void;close:()=>void;project:Project|null}){const items:[Page,string,string][]=[['overview','Overview','⌂'],['project','Project & imagery','▣'],['reconstruction','Configure reconstruction','✦'],['calibration','Run calibration','⌁'],['validation','Run validation','✓'],['terrain','Open 3D terrain','◇'],['inspection','Inspect points','⌖'],['analysis','Error analysis','◌'],['benchmark','Model benchmark','▥'],['history','Compare history','▤'],['exports','Export center','⇩'],['settings','Settings','⚙']];return <div className="palette-backdrop" onClick={close}><div className="palette" onClick={e=>e.stopPropagation()}><div className="palette-title"><span>⌕</span><input autoFocus placeholder="Search DepthWizard workspaces…"/></div><div>{items.map(([p,label,ic])=><button key={p} disabled={!project} onClick={()=>{setPage(p);close()}}><span>{ic}</span>{label}<kbd>↵</kbd></button>)}</div></div></div>}
function Inspector({project,meta,stats,history,inspection,open,setOpen,setPage}:any){const v=history?.validation_history?.[0];return <aside className={`inspector ${open?'':'closed'}`}><button className="inspector-toggle" onClick={()=>setOpen(!open)}>{open?'→':'←'}</button>{open&&<><div className="inspector-head"><div><span className="eyebrow">INSPECTOR</span><h3>{inspection?'Point inspection':'Project context'}</h3></div><Badge state={project.state}/></div>{inspection?<><InspectorMetric label="Elevation" value={`${fmt(inspection.elevation)} ${inspection.unit||'m'}`} big/><div className="inspector-grid"><InspectorMetric label="Relative height" value={inspection.relative_height!==undefined?fmt(inspection.relative_height):'—'}/><InspectorMetric label="Slope" value={inspection.slope!==undefined?`${fmt(inspection.slope)}°`:'—'}/><InspectorMetric label="Pixel" value={`${inspection.pixel_x??'—'}, ${inspection.pixel_y??'—'}`}/><InspectorMetric label="World X" value={fmt(inspection.x,3)}/><InspectorMetric label="World Y" value={fmt(inspection.y,3)}/></div><button className="btn full" onClick={()=>setPage('inspection')}>Open inspection history →</button></>:<><section className="inspector-section"><span>SURFACE</span><InspectorMetric label="Min elevation" value={stats?`${fmt(stats.min_elevation)} ${stats.unit}`:'—'}/><InspectorMetric label="Max elevation" value={stats?`${fmt(stats.max_elevation)} ${stats.unit}`:'—'}/><InspectorMetric label="Mean elevation" value={stats?`${fmt(stats.mean_elevation)} ${stats.unit}`:'—'}/><InspectorMetric label="Range" value={stats?`${fmt(stats.elevation_range)} ${stats.unit}`:'—'}/></section><section className="inspector-section"><span>QUALITY</span><InspectorMetric label="Valid coverage" value={stats?`${fmt(stats.valid_pixel_percentage,1)}%`:'—'}/><InspectorMetric label="Mean slope" value={stats?.slope_mean!==undefined?`${fmt(stats.slope_mean)}°`:'—'}/></section><section className="inspector-section"><span>SPATIAL</span><InspectorMetric label="CRS" value={meta?.crs||'Not georeferenced'}/><InspectorMetric label="Pixel size" value={meta?.resolution?`${fmt(meta.resolution[0],3)} × ${fmt(meta.resolution[1],3)} m`:'—'}/><InspectorMetric label="Raster" value={meta?`${meta.width} × ${meta.height}`:'—'}/></section><section className="inspector-section"><span>VALIDATION</span><InspectorMetric label="Latest RMSE" value={v?`${fmt(v.rmse)} m`:'—'}/><InspectorMetric label="R²" value={v?fmt(v.r2,3):'—'}/><InspectorMetric label="Run" value={history?.current_validation_id||'—'}/></section></>}</>}</aside>}
function InspectorMetric({label,value,big}:{label:string;value:string;big?:boolean}){return <div className={`inspector-metric ${big?'big':''}`}><span>{label}</span><b>{value}</b></div>}
function ConfirmModal({confirm,close,onConfirm}:{confirm:any;close:()=>void;onConfirm:()=>void}){const isRun=confirm.kind==='deleteRun';return <div className="modal-backdrop"><div className="modal"><div className="modal-icon">!</div><h3>{isRun?'Delete history record?':confirm.kind==='reset'?'Reset project?':'Delete project?'}</h3><p>{isRun?`This removes ${confirm.run?.id} from the visible project history. Generated artifacts are not silently overwritten.`:confirm.kind==='reset'?'Reconstruction, calibration, validation, inspection and generated outputs will be removed. Source imagery will be preserved.':'This permanently removes the project and its generated files.'}</p><div className="modal-actions"><button className="btn" onClick={close}>Cancel</button><button className="btn danger" onClick={onConfirm}>{isRun?'Delete':confirm.kind==='reset'?'Reset project':'Delete project'}</button></div></div></div>}
function Exports({project,ready}:any){const assets=[['metric_dsm','Metric DSM · GeoTIFF'],['dsm','Current DSM · GeoTIFF'],['relative_height','Relative height · NPY'],['mesh','Terrain mesh · GLB'],['rgb','Source RGB'],['slope','Slope preview'],['report','Analysis JSON'],['report_html','Analysis HTML'],['error_map','Validation error map']];return <div className="page"><PageHead kicker="EXPORT CENTER" title="Analysis assets" sub="Download standard geospatial, 3D and reproducibility artifacts."/><div className="asset-grid">{assets.map(([a,label])=><a key={a} className="asset-card" href={ready?projectApi.getDownloadUrl(project.project_id,a):'#'} target="_blank" rel="noreferrer"><span>{label}</span><small>{a}</small><strong>↗</strong></a>)}</div><div className="callout"><b>Evidence-ready</b><span>Keep the report, reference data and history together when presenting SIH results. Benchmark numbers are never fabricated by the interface.</span></div></div>}
function SettingsPage({settings,setSettings,modelStatus}:any){const set=(k:string,v:any)=>setSettings((s:ProcessSettings)=>({...s,[k]:v}));return <div className="page"><PageHead kicker="SYSTEM" title="Settings" sub="Application behavior, accuracy policy and local compute."/><div className="two-col"><section className="card"><CardTitle title="Application behavior"/><Toggle label="Remember navigation state" value={true} onChange={()=>{}}/><Toggle label="Auto-open 3D after reconstruction" value={true} onChange={()=>{}}/><Toggle label="Keep history after new runs" value={true} onChange={()=>{}}/><Toggle label="Warn before destructive actions" value={true} onChange={()=>{}}/></section><section className="card"><CardTitle title="Accuracy policy"/><div className="policy-list"><b>✓ Preserve native raster grid</b><b>✓ Overlap tiled inference</b><b>✓ Record inference settings</b><b>✓ Independent holdout validation</b><b>✓ Distinguish DEM from DSM</b><b>✓ Report valid-pixel coverage</b></div></section></div><section className="card"><CardTitle title="Default reconstruction" meta="Used when opening a fresh project"/><div className="form-grid"><Field label="Model"><select value={settings.model_name} onChange={e=>set('model_name',e.target.value)}><option value="depth-anything-v2-small">Small</option><option value="depth-anything-v2-base">Base</option><option value="depth-anything-v2-large">Large</option><option value="aerial-depth" disabled={!modelStatus.find((m:ModelStatus)=>m.id==='aerial-depth')?.available}>Aerial-Depth · not trained</option></select></Field><Field label="Resolution"><select value={settings.inference_resolution} onChange={e=>set('inference_resolution',+e.target.value)}><option value="518">518 px</option><option value="768">768 px</option><option value="1024">1024 px</option></select></Field></div></section></div>}
function PageHead({kicker,title,sub,actions}:{kicker:string;title:string;sub:string;actions?:any}){return <div className="page-head"><div><span className="eyebrow">{kicker}</span><h1>{title}</h1><p>{sub}</p></div>{actions&&<div className="page-actions">{actions}</div>}</div>}
function CardTitle({title,meta}:{title:string;meta?:any}){return <div className="card-title"><h3>{title}</h3>{meta&&<span>{meta}</span>}</div>}
function Metric({label,value,note}:{label:string;value:string;note?:string}){return <div className="metric"><span>{label}</span><b>{value}</b>{note&&<small>{note}</small>}</div>}
function DataRows({rows}:{rows:any[][]}){return <div className="data-rows">{rows.map(([a,b],i)=><div key={i}><span>{a}</span><b>{b===undefined||b===null||b===''?'—':String(b)}</b></div>)}</div>}
function HealthRow({label,ok,text}:{label:string;ok:boolean;text:string}){return <div className="health-row"><span className={ok?'check':'dash'}>{ok?'✓':'—'}</span><div><b>{label}</b><small>{text}</small></div><strong>{ok?'Ready':'Pending'}</strong></div>}
function Field({label,children}:{label:string;children:any}){return <label className="field"><span>{label}</span>{children}</label>}
function Toggle({label,value,onChange}:{label:string;value:boolean;onChange:(v:boolean)=>void}){return <label className="toggle"><span>{label}</span><input type="checkbox" checked={value} onChange={e=>onChange(e.target.checked)}/><i/></label>}
function Step({n,t,s,state}:{n:string;t:string;s:string;state?:'done'|'active'|''}){return <div className={`pipe-step ${state||''}`}><span>{state==='done'?'✓':n}</span><div><b>{t}</b><small>{s}</small></div><strong>{state==='done'?'✓':state==='active'?'●':'○'}</strong></div>}
function Progress({project}:{project:Project}){const pct=Math.max(0,Math.min(100,Math.round((project.progress||0)*100)));const started=project.started_at?new Date(project.started_at*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';return <div className="progress-card live-progress"><div><span><b>LIVE PROCESSING</b></span><strong>{pct}%</strong></div><div className="progress"><i style={{width:`${pct}%`}}/></div><div className="progress-stage"><b>{project.progress_stage||project.state.replace(/_/g,' ')}</b><span>{project.message||'Working…'}</span></div><div className="progress-meta"><span>Backend: {project.job_state||'processing'}</span><span>Started {started}</span></div></div>}
function EmptyHint({text,action,onClick}:{text:string;action:string;onClick?:()=>void}){return <div className="empty-hint"><span>◇</span><p>{text}</p>{onClick&&<button onClick={onClick}>{action} →</button>}</div>}
function HistoryStrip({title,count}:{title:string;count:number}){return <section className="card"><CardTitle title={title} meta={`${count} preserved`}/><p className="muted">Every run is persisted in project state and the local SQLite analysis store. New runs do not overwrite earlier records.</p></section>}
function HistoryTimeline({rows}:{rows:any[]}){return <div className="timeline">{rows.length?rows.map((x:any,i:number)=><div className="timeline-row" key={`${x._type}-${x.run_id}-${i}`}><span className="timeline-dot">✓</span><div><b>{x._type} {x.run_id||''}</b><small>{dt(x.created_at)} · {x.model||x.method||''}</small></div><strong>{x.rmse!==undefined?`${fmt(x.rmse)} m`:x.processing_seconds?`${fmt(x.processing_seconds,1)} s`:''}</strong></div>):<EmptyHint text="No analysis runs yet." action="Run reconstruction"/>}</div>}
function HistoryTable({rows}:{rows:any[]}){return <div className="history-table">{rows.length?rows.slice(0,12).map((x:any)=><div key={x.id} className="history-table-row"><span><b>{x.id}</b><small>{dt(x.date)}</small></span><strong>{x.value}</strong><small>{x.sub}</small></div>):<div className="muted">No saved points yet.</div>}</div>}
function Check({ok,text}:{ok:boolean;text:string}){return <div className={ok?'check-card ok':'check-card'}><span>{ok?'✓':'—'}</span><b>{text}</b></div>}
function Insight({title,text}:{title:string;text:string}){return <div className="insight"><b>{title}</b><p>{text}</p></div>}
